/**
 * HTML mail sanitiser (ADR 0006 decision 8).
 *
 * Mail HTML is parsed by DOMPurify into an inert document (DOMParser: no
 * browsing context, so nothing loads and no handler can run), cleaned there,
 * post-processed there, and serialised from there. The result is only ever
 * parsed again inside the sandboxed message frame. It is never parsed into the
 * app document (no innerHTML on app nodes), so a parser differential cannot
 * reach the app's realm or its IPC.
 *
 * After sanitising:
 * - no element has `href`; links keep their element and carry the target in
 *   `data-eos-href` (http, https and mailto only);
 * - `cid:` images carry `data-eos-cid`; remote https images carry
 *   `data-eos-src` / `data-eos-background` until the user loads images;
 * - style attributes and `<style>` text are filtered by `css-filter.ts`;
 * - a trailing quote is marked `data-eos-quote="trailing"`.
 */
import createDOMPurify from 'dompurify';
import { filterCss, filterStyleAttribute } from './css-filter';

export interface SanitizedMail {
  /** Filtered text of every `<style>` element, for the frame's head. */
  styles: string;
  /** `<div class="eos-mail-body" …>…</div>`: the cleaned body content. */
  body: string;
  /** Remote resources withheld because remote images are not loaded. */
  remoteBlocked: number;
  /** Content-IDs referenced by `cid:` images, unique, in document order. */
  cidReferences: string[];
  /** Whether the mail sets its own text or background colours (paper card). */
  hasOwnColours: boolean;
  /** Whether a trailing quote was found and marked. */
  hasTrailingQuote: boolean;
}

export interface SanitizeOptions {
  /** True once the user chose "Load images" for this message. */
  remoteImages: boolean;
}
    } else {
      element.removeAttribute('style');
    }
  }

  if (declaresColours(element)) result.hasOwnColours = true;
}

/** Moves an `<a href>` target to `data-eos-href`; no `href` survives anywhere. */
function cleanLink(element: Element): void {
  const href = element.getAttribute('href');
  if (href === null) return;
  element.removeAttribute('href');
  if (element.tagName !== 'A') return;
  let url: URL;
  try {
    url = new URL(href.trim());
  } catch {
    return; // Relative and malformed links are dropped.
  }
  if (!LINK_PROTOCOLS.has(url.protocol)) return;
  element.setAttribute('data-eos-href', url.href);
  element.setAttribute('role', 'link');
  element.setAttribute('tabindex', '0');
}

/** `cid:` → data-eos-cid; data images stay; https → src or withheld; else dropped. */
function cleanImageAttribute(
  element: Element,
  attribute: 'src' | 'background',
  options: SanitizeOptions,
  result: SanitizedMail,
  contentIds: Set<string>,
): void {
  const value = element.getAttribute(attribute)?.trim();
  element.removeAttribute(attribute);
  if (!value) return;

  if (/^cid:/i.test(value)) {
    let cid: string;
    try {
      cid = decodeURIComponent(value.slice(4));
    } catch {
      return; // Invalid percent-encoding is dropped.
    }
    if (!cid) return;
    element.setAttribute('data-eos-cid', cid);
    contentIds.add(cid);
    return;
  }
  if (DATA_IMAGE.test(value)) {
    element.setAttribute(attribute, value);
    return;
  }
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    return; // Relative and malformed URLs are dropped.
  }
  if (url.protocol !== 'https:') return;
  if (options.remoteImages) {
    element.setAttribute(attribute, url.href);
  } else {
    element.setAttribute(attribute === 'background' ? 'data-eos-background' : 'data-eos-src', url.href);
    result.remoteBlocked += 1;
  }
}

/** Presentational colour attributes (ADR 0006 decision 15). */
function declaresColours(element: Element): boolean {
  if (element.hasAttribute('bgcolor') || element.hasAttribute('background')) return true;
  if (element.hasAttribute('data-eos-background')) return true;
  if (element.tagName === 'FONT' && element.hasAttribute('color')) return true;
  if (element.tagName === 'BODY' && (element.hasAttribute('text') || element.hasAttribute('link'))) {
    return true;
  }
  return false;
}
import { flushPromises, mount } from '@vue/test-utils';
import { expect, it, vi } from 'vitest';
import HtmlMessageFrame from '../../src/components/HtmlMessageFrame.vue';
import type { MailClient } from '../../src/lib/ipc/client';

const theme = { fontFamily: 'sans-serif', fontSize: '15px', lineHeight: '24px', textColour: '#fff', linkColour: '#fff' };
const conversation = { accountId: 'test', conversationId: 'frame-test' };

it('renders a sandboxed sanitized document', async () => {
  const client = { getMessageHtml: vi.fn().mockResolvedValue({ html: '<script>bad()</script><a href="https://example.test">Link</a>', inlineImages: [] }) } as unknown as MailClient;
  const wrapper = mount(HtmlMessageFrame, { props: { client, conversation, messageId: 'one', title: 'Message from Ana', remoteImages: false, quoteOpen: false, theme } });
  await flushPromises();
  const iframe = wrapper.get('iframe');
  expect(iframe.attributes('sandbox')).toBe('allow-same-origin');
  expect(iframe.attributes('referrerpolicy')).toBe('no-referrer');
  expect(iframe.attributes('title')).toBe('Message from Ana');
  const doc = iframe.attributes('srcdoc') ?? '';
  expect(doc.startsWith('<!doctype html>')).toBe(true);
  expect(doc).toContain('Content-Security-Policy');
  expect(doc).not.toMatch(/\shref=/);
  expect(doc).not.toContain('<script');
  wrapper.unmount();
});

it('reports fetch failures', async () => {
  const client = { getMessageHtml: vi.fn().mockRejectedValue(new Error('failed')) } as unknown as MailClient;
  const wrapper = mount(HtmlMessageFrame, { props: { client, conversation, messageId: 'error', title: 'Message', remoteImages: false, quoteOpen: false, theme } });
  await flushPromises();
  expect(wrapper.emitted('fallback')).toEqual([['error']]);
  wrapper.unmount();
});

it('renders a cached message again after the reader remounts', async () => {
  const client = { getMessageHtml: vi.fn().mockResolvedValue({ html: '<p>Cached body</p>', inlineImages: [] }) } as unknown as MailClient;
  const props = { client, conversation, messageId: 'cached', title: 'Message', remoteImages: false, quoteOpen: false, theme };
  const first = mount(HtmlMessageFrame, { props });
  await flushPromises();
  expect(first.get('iframe').attributes('srcdoc')).toContain('Cached body');
  first.unmount();

  const second = mount(HtmlMessageFrame, { props });
  await flushPromises();
  expect(client.getMessageHtml).toHaveBeenCalledTimes(1);
  expect(second.get('iframe').attributes('srcdoc')).toContain('Cached body');
  second.unmount();
});

it('keeps links working when a refresh replaces the conversation object', async () => {
  const client = { getMessageHtml: vi.fn().mockResolvedValue({ html: '<a href="https://example.test/">Link</a>', inlineImages: [] }) } as unknown as MailClient;
  const props = { client, conversation, messageId: 'refreshed', title: 'Message', remoteImages: false, quoteOpen: false, theme };
  const wrapper = mount(HtmlMessageFrame, { props, attachTo: document.body });
  await flushPromises();
  const clickLink = (): void => {
    const doc = (wrapper.get('iframe').element as HTMLIFrameElement).contentDocument!;
    if (!doc.querySelector('a')) {
      doc.body.innerHTML = '<a data-eos-href="https://example.test/">Link</a>';
    }
    doc.querySelector('a')!.click();
  };
  await wrapper.get('iframe').trigger('load');
  clickLink();
  expect(wrapper.emitted('link')).toHaveLength(1);

  const before = wrapper.get('iframe').element;
  await wrapper.setProps({ conversation: { ...conversation } });
  await flushPromises();
  expect(wrapper.get('iframe').element).toBe(before);
  clickLink();
  expect(wrapper.emitted('link')).toHaveLength(2);
  wrapper.unmount();
});
